import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.Dsf4_p3t.js";const p=JSON.parse('{"title":"EventLoop","description":"","frontmatter":{},"headers":[],"relativePath":"api/event-loop.md","filePath":"api/event-loop.md","lastUpdated":1786973110000}'),r={name:"api/event-loop.md"};function l(c,e,i,n,s,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="eventloop" tabindex="-1">EventLoop <a class="header-anchor" href="#eventloop" aria-label="Permalink to &quot;EventLoop&quot;">​</a></h1><p>CV-driven frame scheduler, coroutine scheduler, and timer queue.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>EventLoop</code> manages the application&#39;s main loop, running at a target frame rate. It supports C++20 coroutine scheduling via <code>Schedule()</code>, one-frame yields via <code>ScheduleYield()</code>, and timed resumes via <code>ScheduleSleep()</code>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>Run(frame_callback)</code></td><td>Start the event loop, blocks until <code>Stop()</code></td></tr><tr><td><code>Stop()</code></td><td>Stop the event loop</td></tr><tr><td><code>WakeUp()</code></td><td>Wake the loop from idle wait</td></tr><tr><td><code>Schedule(task)</code></td><td>Schedule a <code>Task&lt;void&gt;</code> coroutine</td></tr><tr><td><code>ScheduleYield(handle)</code></td><td>Resume a handle on the next frame (used by <code>Yield()</code>)</td></tr><tr><td><code>ScheduleSleep(duration, handle)</code></td><td>Resume a handle after a duration (used by <code>Sleep()</code>)</td></tr><tr><td><code>SetTargetFps(fps)</code></td><td>Set target frame rate</td></tr><tr><td><code>GetTargetFps() -&gt; int</code></td><td>Get target frame rate</td></tr><tr><td><code>GetFrameCount() -&gt; uint64_t</code></td><td>Get frames processed</td></tr></tbody></table><h2 id="coroutine-lifecycle" tabindex="-1">Coroutine Lifecycle <a class="header-anchor" href="#coroutine-lifecycle" aria-label="Permalink to &quot;Coroutine Lifecycle&quot;">​</a></h2><p>The loop uses <code>shared_ptr&lt;Task&lt;void&gt;&gt;</code> for all scheduled coroutines. An <code>active_tasks_</code> map (keyed by handle address) holds shared ownership, ensuring a coroutine frame is not destroyed while a timer or yield-pending handle still references it. See <a href="./../guide/coroutines">Coroutines</a> for details.</p><h2 id="thread-safety" tabindex="-1">Thread Safety <a class="header-anchor" href="#thread-safety" aria-label="Permalink to &quot;Thread Safety&quot;">​</a></h2><p><code>Schedule()</code>, <code>ScheduleYield()</code>, and <code>ScheduleSleep()</code> are guarded by a mutex and may be called from any thread. <code>WakeUp()</code> is thread-safe.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./task">Task</a></li><li><a href="./application">Application</a></li><li><a href="./../guide/coroutines">Coroutines Guide</a></li></ul>',12)])])}const f=t(r,[["render",l]]);export{p as __pageData,f as default};
